import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.DfDAiEgj.js";const i="/2bPM/img/page_axure.png",l="/2bPM/img/lock_axure.png",n="/2bPM/img/close_axure.png",s="/2bPM/img/page2_axure.png",p="/2bPM/img/ant_design2axure.png",c="/2bPM/img/remove_now_lib_axure.png",m="/2bPM/img/svg2image.png",h="/2bPM/img/image_color.png",g="/2bPM/img/awesomeicon_axure.png",_="/2bPM/img/kuang0_axure.png",u="/2bPM/img/page_done.png",f="/2bPM/img/UI_design_docs.png",A=JSON.parse('{"title":"静态页面","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/static_page.md","filePath":"knowledge/static_page.md","lastUpdated":null}'),d={name:"knowledge/static_page.md"};function b(w,e,x,k,P,q){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="静态页面" tabindex="-1">静态页面 <a class="header-anchor" href="#静态页面" aria-label="Permalink to &quot;静态页面&quot;">​</a></h1><p>导航信息、组件元素、页面布局-栅格系统、文案信息、重要备注 <a href="https://www.yinxiang.com/everhub/note/f9ab87ee-73e6-4241-9428-9507cbfd007f" target="_blank" rel="noreferrer">1</a></p><h2 id="低保真-axure实战" tabindex="-1">低保真 Axure实战 <a class="header-anchor" href="#低保真-axure实战" aria-label="Permalink to &quot;低保真 Axure实战&quot;">​</a></h2><p>大小 <a href="https://www.bilibili.com/video/BV1WE411w7LW?p=3" target="_blank" rel="noreferrer">2</a>： <img src="'+i+'" alt="页面Axure实战(375*667)"></p><p>锁定： <img src="'+l+'" alt="锁定"></p><p>关闭按钮： <img src="'+n+'" alt="关闭按钮"></p><p>整体： <img src="'+s+'" alt="页面Axure实战(375*667)"></p><h2 id="高保真-axure实战" tabindex="-1">高保真 Axure实战 <a class="header-anchor" href="#高保真-axure实战" aria-label="Permalink to &quot;高保真 Axure实战&quot;">​</a></h2><p><a href="https://library.ant.design/" target="_blank" rel="noreferrer">https://library.ant.design/</a></p><p>下载，解压</p><p><img src="'+p+'" alt="导入原型库"></p><p><img src="'+c+'" alt="移出当前原型库"></p><p>图标：<a href="https://www.iconfont.cn/" target="_blank" rel="noreferrer">https://www.iconfont.cn/</a></p><p>登录失败。。</p><p><img src="'+m+'" alt="svg到图片"></p><p><img src="'+h+'" alt="图片黄色"></p><p><img src="'+g+'" alt="awesomeicon_axure"></p><p><a href="https://www.flaticon.com/search?word=close" target="_blank" rel="noreferrer">https://www.flaticon.com/search?word=close</a></p><p>对齐：先圆形后图标，居中</p><p>卡死了，为啥？</p><p><img src="'+_+'" alt="0框"></p><p>勉强做完，实在登不上iconfont..QQ找不到，wechat用的flaticon</p><p><img src="'+u+'" alt="制作完成"></p><h2 id="交互设计图-——-只做交互相关解释" tabindex="-1">交互设计图 —— 只做交互相关解释 <a class="header-anchor" href="#交互设计图-——-只做交互相关解释" aria-label="Permalink to &quot;交互设计图 —— 只做交互相关解释&quot;">​</a></h2><h3 id="什么是「交互文档」" tabindex="-1">什么是「交互文档」？ <a class="header-anchor" href="#什么是「交互文档」" aria-label="Permalink to &quot;什么是「交互文档」？&quot;">​</a></h3><ul><li>交互文档也称DRD，是用来告诉别人「页面设计细节」的一个说明文档。</li><li>包括页面跳转逻辑、页面交互逻辑、页面显示状态等细节的说明。<a href="https://www.zhihu.com/question/19825650/answer/758117107" target="_blank" rel="noreferrer">4</a></li></ul><h3 id="为什么要写交互文档" tabindex="-1">为什么要写交互文档？ <a class="header-anchor" href="#为什么要写交互文档" aria-label="Permalink to &quot;为什么要写交互文档？&quot;">​</a></h3><ul><li>交互设计师的工作就是完善细节设计，那你设计的这些细节应该如何告诉开发呢？口述当然是不行的了，第一是记不住，第二是会理解错误，第三就是最重要的一点，没有历史记录。</li><li>现在办公用的聊天软件非常多，但是所有企业依然使用邮件的方式沟通，这正是因为邮件可以作为沟通证据保存下来，没有沟通记录就等于没说，交互文档也是一个道理，你要把你做的所有细节都写下来，给其他人发邮件，告诉对方要做什么、要怎么做。</li></ul><h3 id="交互文档给谁看" tabindex="-1">交互文档给谁看？ <a class="header-anchor" href="#交互文档给谁看" aria-label="Permalink to &quot;交互文档给谁看？&quot;">​</a></h3><p><strong>交互设计文档</strong>主要是<strong>给前端和UI看的文档</strong>，所以文档的说明应<strong>不包含业务解释、规则说明</strong>相关的内容。可以借用需求文档的思路，还是先排版，页面分为“准高保证原型图”、“注释说明”、“交互”、“其他补充内容”。<a href="http://www.woshipm.com/pmd/418829.html" target="_blank" rel="noreferrer">3</a></p><ul><li>给产品经理看：交互逻辑、交互方式，需要与产品经理确认。产品经理是把控整个产品的一个角色，任何事情他都需要做到心里有数，包括交互设计。</li><li>给UI设计师看：交互设计会包含很多状态、很多细节、很多页面，UI设计师要确保每一个状态、每一个页面都画出来，这样在开发的时候才不会漏掉东西。</li><li>给开发人员看：代码逻辑和我们普通说话的逻辑不同，说话的时候可以是点击这里跳转页面，而程序员需要知道点击什么位置，使用什么方式跳转到哪一个页面，中途需要判断哪些规则，如果中途失败怎么办...因此交互文档就更重要了。</li><li>给测试人员看：测试岗位也称QA，属于研发部门旗下的一个岗位（很多小公司没有这个岗位），你需要把你所有的设计细节都告诉他，然后他去测试一遍最终效果与你设计的是否完全一致（不包括UI）。</li></ul><h3 id="内容" tabindex="-1">内容 <a class="header-anchor" href="#内容" aria-label="Permalink to &quot;内容&quot;">​</a></h3><p><img src="'+f+'" alt="交互设计文档"></p><ul><li>文档页面标题：一般在每一页文档的顶部。写明当页内容是属于哪个模块或流程的，让看的人不容易迷失；</li><li>界面标题：注意命名，方便交互稿中的互相联系，如“跳转【XX页面】”，“回到【XX界面】状态”；</li><li>界面：界面尺寸建议按实际界面的比例缩小，避免你想当然的设计并不符合规范，也避免一个界面太大影响阅读效果；</li><li>设计说明：逻辑关系、操作流程或反馈、元素状态、字符限制、异常/特殊状态 等等，都可以放在设计说明中；</li><li>交互说明：提示弹框样式、功能实现方式、提示内容等响应用户物理操作的反馈画面。</li><li>流程线：说明界面间逻辑关系；</li><li>跳转链接：指向其他页面，例如某子流程，开发伙伴阅读起来会很方便。</li><li>注释说明：应该包括输入检测标准、缺省值、界面元素变化、显示上限等情景的说明。</li></ul><h2 id="更多" tabindex="-1">更多 <a class="header-anchor" href="#更多" aria-label="Permalink to &quot;更多&quot;">​</a></h2><ul><li><a href="https://www.axurethemes.com/axure-icon-packs" target="_blank" rel="noreferrer">https://www.axurethemes.com/axure-icon-packs</a></li><li><a href="https://fontawesome.com/download" target="_blank" rel="noreferrer">https://fontawesome.com/download</a></li><li><a href="https://forum.axure.com/t/4-steps-to-get-fontawesome-5-11-2-free-axure-9-working/65942" target="_blank" rel="noreferrer">https://forum.axure.com/t/4-steps-to-get-fontawesome-5-11-2-free-axure-9-working/65942</a></li><li><a href="https://fontawesome.com/icons?d=gallery&amp;p=2&amp;q=close" target="_blank" rel="noreferrer">https://fontawesome.com/icons?d=gallery&amp;p=2&amp;q=close</a></li><li><a href="https://github.com/bsdfzzzy/iconfont-all-in-one" target="_blank" rel="noreferrer">https://github.com/bsdfzzzy/iconfont-all-in-one</a></li><li><a href="http://caibaojian.com/font-awesome.html" target="_blank" rel="noreferrer">http://caibaojian.com/font-awesome.html</a></li></ul>',36)])])}const v=a(d,[["render",b]]);export{A as __pageData,v as default};
